export declare const TILES_CSS = "\n.kit-tiles{display:flex;flex-direction:column;gap:12px;color:var(--mp-text)}\n.kit-tiles-title{margin:0;font-size:18px;font-weight:700}\n.kit-tiles-grid{list-style:none;margin:0;padding:0;display:grid;gap:12px 8px;grid-template-columns:repeat(3,minmax(0,1fr))}\n.kit-tiles[data-columns=\"4\"] .kit-tiles-grid{grid-template-columns:repeat(4,minmax(0,1fr))}\n.kit-tile{min-width:0}\n.kit-tiles button.kit-tile-open{position:relative;width:100%;min-height:0;padding:4px;border:0;background:none;color:inherit;\n display:flex;flex-direction:column;align-items:center;gap:4px;font:inherit}\n.kit-tile-ring{width:min(88px,100%);aspect-ratio:1;box-sizing:border-box;border-radius:50%;padding:5px;display:flex;\n background:conic-gradient(var(--mp-mint) var(--kit-progress,0%),var(--mp-line) 0)}\n.kit-tile-ring>img,.kit-tile-ring>.kit-letter{width:100%;height:100%;border-radius:50%;object-fit:cover;\n background:var(--mp-surface);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:24px}\n.kit-tile-done{position:absolute;top:4px;right:calc(50% - 44px);width:24px;height:24px;border-radius:50%;\n display:flex;align-items:center;justify-content:center;background:var(--mp-mint);color:var(--mp-on-accent,#fff);font-weight:800}\n.kit-tile-name{max-width:100%;font-weight:700;font-size:13px;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.kit-tile-count{font-weight:600;font-size:12px;color:var(--mp-text-3)}\n.kit-tile .kit-meter{flex:none;width:80%;--kit-meter-h:6px}\n";
